-- LF M4, 112 fuentes inventariadas, 8 candidatas; ninguna regla publicada ni deprecada.
-- Fuente fichas: sandbox/lf_contract_gate_test/nucleo_ci/m4_8_candidatas_v1.json
BEGIN;
DO $m4$
DECLARE p jsonb; dry jsonb; applied jsonb; eval jsonb; t jsonb; truth jsonb; bad jsonb; mutant_truth jsonb;
 code text; ref_id integer; n integer:=0; cases integer; total_tests integer:=0; actual_sources integer;
 oldlegacy jsonb; oldrules jsonb; oldversions jsonb; olddeprec jsonb; oldapps jsonb; oldeffective jsonb; oldekb integer;
BEGIN
 SELECT count(*) INTO actual_sources FROM lf_ops.nucleo_regla_familia f
 JOIN lf_ops.v_reglas_compat_v1 v ON v.id=f.regla_id WHERE f.familia IN ('SECURITY','MFA_OTP_SSO','SESSION','RATE_LIMIT');
 IF actual_sources<>112 OR EXISTS (SELECT 1 FROM lf_ops.nucleo_reglas WHERE codigo LIKE 'M4-C0%') THEN RAISE EXCEPTION 'M4_SOURCE_OR_ID_DRIFT %',actual_sources; END IF;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY id) INTO oldlegacy FROM lf_ops.reglas r;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY codigo) INTO oldrules FROM lf_ops.nucleo_reglas r;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) INTO oldversions FROM lf_ops.nucleo_regla_versiones r;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) INTO olddeprec FROM lf_ops.nucleo_deprecaciones r;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,nodo) INTO oldapps FROM lf_ops.nucleo_aplicaciones r;
 SELECT jsonb_agg(jsonb_build_object('nodo',nd.codigo,'r',to_jsonb(e)) ORDER BY nd.codigo,e.regla)
 INTO oldeffective FROM lf_ops.nucleo_nodos nd CROSS JOIN LATERAL lf_ops.nucleo_reglas_efectivas_v1(nd.codigo,now()) e;
 SELECT count(*) INTO oldekb FROM public.lf_error_knowledge;
 FOR code IN SELECT jsonb_array_elements_text('["m4_intento_exponer_dni","m4_dni_expuesto_en_canal_no_permitido","m4_intento_transportar_sesion","m4_sesion_incluida_en_url","m4_intento_responder_api_otp","m4_respuesta_api_contiene_otp","m4_intento_respuesta_dni_protegida","m4_respuesta_dni_revela_existencia","m4_intento_respuesta_celular_protegida","m4_respuesta_celular_revela_existencia","m4_intento_identidad_o_rebind_por_otp","m4_otp_unica_prueba_sin_identidad","m4_onb003_intento_persistir_dni_cliente","m4_dni_persistencia_cliente_prohibida","m4_onb003_intento_responder_resolucion","m4_onb003_respuesta_revela_cuenta"]'::jsonb) LOOP
  IF EXISTS (SELECT 1 FROM lf_ops.nucleo_hechos WHERE codigo=code) THEN RAISE EXCEPTION 'M4_FACT_COLLISION %',code; END IF;
  INSERT INTO lf_ops.nucleo_hechos(codigo,tipo_dato,unidad,descripcion) VALUES (code,'boolean','ninguna','Hecho lógico M4 seguridad, fuente backend/cliente y binding Paulo pendientes; tabla_ref y columna_ref NULL');
  INSERT INTO lf_ops.nucleo_familia_vocabulario(familia,hecho,origen) VALUES('SECURITY',code,'CURADO');
 END LOOP;
 FOR p IN SELECT value FROM jsonb_array_elements('[{"tipo":"NUEVA","codigo":"M4-C01","clave":"m4_seg_guard_21","titulo":"No exponer DNI en telemetría","descripcion":"Cuando se intenta registrar DNI en logs, analytics, headers o mensajes de error BLOQUEAR la exposición de PII. No bloquea otras operaciones sin intento de exposición.","familia":"SECURITY","naturaleza":"CONDUCTA","autoridad":"LEG-SEGURIDAD","dueno":"SEGURIDAD","alcance":"BACKEND","modo":"HEREDA","clase":"BACKEND","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m4_intento_exponer_dni"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m4_dni_expuesto_en_canal_no_permitido"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/21","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m4_intento_exponer_dni":true,"m4_dni_expuesto_en_canal_no_permitido":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4_intento_exponer_dni":true,"m4_dni_expuesto_en_canal_no_permitido":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4_intento_exponer_dni":false,"m4_dni_expuesto_en_canal_no_permitido":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4_intento_exponer_dni":false,"m4_dni_expuesto_en_canal_no_permitido":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M4-C02","clave":"m4_seg_guard_24","titulo":"No transportar token de sesión en URL","descripcion":"Ante intento de construir URL con identificador de sesión, BLOQUEAR su inclusión como parámetro GET; el transporte autorizado corresponde a header o cookie httpOnly. No bloquear solicitudes sin transporte de sesión.","familia":"SECURITY","naturaleza":"CONDUCTA","autoridad":"LEG-SEGURIDAD","dueno":"SEGURIDAD","alcance":"BACKEND","modo":"HEREDA","clase":"BACKEND","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m4_intento_transportar_sesion"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m4_sesion_incluida_en_url"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/24","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m4_intento_transportar_sesion":true,"m4_sesion_incluida_en_url":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4_intento_transportar_sesion":true,"m4_sesion_incluida_en_url":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4_intento_transportar_sesion":false,"m4_sesion_incluida_en_url":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4_intento_transportar_sesion":false,"m4_sesion_incluida_en_url":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M4-C03","clave":"m4_seg_guard_62","titulo":"No devolver código OTP por respuesta API","descripcion":"Ante intento de construir una respuesta API OTP, BLOQUEAR si incluye el secreto otp_code; permitir solo resultado de envío/verificación sin secreto. No bloquear otras respuestas API.","familia":"SECURITY","naturaleza":"CONDUCTA","autoridad":"LEG-SEGURIDAD","dueno":"SEGURIDAD","alcance":"BACKEND","modo":"HEREDA","clase":"BACKEND","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m4_intento_responder_api_otp"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m4_respuesta_api_contiene_otp"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/62","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m4_intento_responder_api_otp":true,"m4_respuesta_api_contiene_otp":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4_intento_responder_api_otp":true,"m4_respuesta_api_contiene_otp":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4_intento_responder_api_otp":false,"m4_respuesta_api_contiene_otp":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4_intento_responder_api_otp":false,"m4_respuesta_api_contiene_otp":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M4-C04","clave":"m4_seg_guard_128","titulo":"No enumerar DNI en validación protegida","descripcion":"Ante intento de responder por un DNI registrado, bloqueado o sospechoso, BLOQUEAR si el mensaje revela existencia o estado del DNI; la respuesta al usuario debe ser genérica. No imponerlo a consultas fuera de validación protegida.","familia":"SECURITY","naturaleza":"CONDUCTA","autoridad":"LEG-SEGURIDAD","dueno":"SEGURIDAD","alcance":"BACKEND","modo":"HEREDA","clase":"BACKEND","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m4_intento_respuesta_dni_protegida"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m4_respuesta_dni_revela_existencia"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/128","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m4_intento_respuesta_dni_protegida":true,"m4_respuesta_dni_revela_existencia":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4_intento_respuesta_dni_protegida":true,"m4_respuesta_dni_revela_existencia":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4_intento_respuesta_dni_protegida":false,"m4_respuesta_dni_revela_existencia":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4_intento_respuesta_dni_protegida":false,"m4_respuesta_dni_revela_existencia":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M4-C05","clave":"m4_seg_guard_129","titulo":"No enumerar celular en validación protegida","descripcion":"Ante intento de responder por celular registrado o bloqueado, BLOQUEAR si el mensaje revela existencia o estado del celular; usar respuesta genérica. No alterar respuestas ajenas a consulta protegida.","familia":"SECURITY","naturaleza":"CONDUCTA","autoridad":"LEG-SEGURIDAD","dueno":"SEGURIDAD","alcance":"BACKEND","modo":"HEREDA","clase":"BACKEND","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m4_intento_respuesta_celular_protegida"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m4_respuesta_celular_revela_existencia"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/129","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m4_intento_respuesta_celular_protegida":true,"m4_respuesta_celular_revela_existencia":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4_intento_respuesta_celular_protegida":true,"m4_respuesta_celular_revela_existencia":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4_intento_respuesta_celular_protegida":false,"m4_respuesta_celular_revela_existencia":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4_intento_respuesta_celular_protegida":false,"m4_respuesta_celular_revela_existencia":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M4-C06","clave":"m4_seg_guard_456","titulo":"OTP celular no acredita identidad civil","descripcion":"Ante intento de atribuir identidad civil o reasignar cuenta existente, BLOQUEAR si solo consta prueba de control del celular por OTP y falta acreditación de identidad o recuperación autorizada. No bloquear verificación OTP ordinaria sin reasignación.","familia":"SECURITY","naturaleza":"CONDUCTA","autoridad":"LEG-SEGURIDAD","dueno":"SEGURIDAD","alcance":"BACKEND","modo":"HEREDA","clase":"BACKEND","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m4_intento_identidad_o_rebind_por_otp"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m4_otp_unica_prueba_sin_identidad"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/456","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m4_intento_identidad_o_rebind_por_otp":true,"m4_otp_unica_prueba_sin_identidad":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4_intento_identidad_o_rebind_por_otp":true,"m4_otp_unica_prueba_sin_identidad":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4_intento_identidad_o_rebind_por_otp":false,"m4_otp_unica_prueba_sin_identidad":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4_intento_identidad_o_rebind_por_otp":false,"m4_otp_unica_prueba_sin_identidad":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M4-C07","clave":"m4_seg_guard_492","titulo":"DNI no persiste en almacenamiento cliente","descripcion":"En el paso ONB_003, ante intento de persistencia de DNI en navegador, BLOQUEAR localStorage, sessionStorage, URL, analytics, replay o caché offline. La validación server-side queda fuera de este guard.","familia":"SECURITY","naturaleza":"CONDUCTA","autoridad":"LEG-SEGURIDAD","dueno":"SEGURIDAD","alcance":"CLIENT_ONBOARDING","modo":"HEREDA","clase":"PANTALLA","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m4_onb003_intento_persistir_dni_cliente"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m4_dni_persistencia_cliente_prohibida"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/492","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m4_onb003_intento_persistir_dni_cliente":true,"m4_dni_persistencia_cliente_prohibida":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4_onb003_intento_persistir_dni_cliente":true,"m4_dni_persistencia_cliente_prohibida":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4_onb003_intento_persistir_dni_cliente":false,"m4_dni_persistencia_cliente_prohibida":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4_onb003_intento_persistir_dni_cliente":false,"m4_dni_persistencia_cliente_prohibida":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M4-C08","clave":"m4_seg_guard_499","titulo":"No enumerar cuenta desde ONB_003","descripcion":"En resolución server-side ONB_003, ante intento de respuesta al cliente, BLOQUEAR flags, códigos o mensajes que expongan explícitamente existencia de cuenta por DNI. No bloquea navegación posterior autorizada sin divulgación explícita.","familia":"SECURITY","naturaleza":"CONDUCTA","autoridad":"LEG-SEGURIDAD","dueno":"SEGURIDAD","alcance":"BACKEND","modo":"HEREDA","clase":"BACKEND","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m4_onb003_intento_responder_resolucion"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m4_onb003_respuesta_revela_cuenta"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/499","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m4_onb003_intento_responder_resolucion":true,"m4_onb003_respuesta_revela_cuenta":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4_onb003_intento_responder_resolucion":true,"m4_onb003_respuesta_revela_cuenta":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4_onb003_intento_responder_resolucion":false,"m4_onb003_respuesta_revela_cuenta":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4_onb003_intento_responder_resolucion":false,"m4_onb003_respuesta_revela_cuenta":false},"esperado":false}]}]'::jsonb) LOOP
  code:=p->>'codigo'; ref_id:=split_part(p->'origen'->>'ref','/',2)::integer;
  IF NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_familia f JOIN lf_ops.v_reglas_compat_v1 v ON v.id=f.regla_id WHERE f.familia IN ('SECURITY','MFA_OTP_SSO','SESSION','RATE_LIMIT') AND v.id=ref_id)
  THEN RAISE EXCEPTION 'M4_LEGACY_NOT_FOUND % %',code,ref_id; END IF;
  dry:=lf_ops.nucleo_regla_proponer_v1(p,false);
  IF dry->>'resultado'<>'EVALUADA_SIN_ESCRIBIR' OR (dry->>'bloqueantes')::integer<>0 THEN RAISE EXCEPTION 'M4_PREFLIGHT % %',code,dry; END IF;
  cases:=0;
  FOR t IN SELECT value FROM jsonb_array_elements(p->'pruebas') LOOP
    truth:=lf_ops.nucleo_eval_v1(p->'condicion',t->'entrada');
    IF truth IS DISTINCT FROM t->'esperado' THEN RAISE EXCEPTION 'M4_WRONG_CONTROL % case=% expected=% actual=%',code,cases,t->'esperado',truth; END IF;
    cases:=cases+1;
  END LOOP;
  IF cases<>4 THEN RAISE EXCEPTION 'M4_CASE_COVERAGE %',code; END IF;
  SELECT value INTO bad FROM jsonb_array_elements(p->'pruebas') WITH ORDINALITY x(value,ord) WHERE ord=3;
  IF bad->'esperado' IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION 'M4_MUTANT_NEGATIVE_CASE_MISSING %',code; END IF;
  -- Remove scope guard (left operand): must activate erroneously on the scope-inactive test.
  mutant_truth:=lf_ops.nucleo_eval_v1(p->'condicion'->'der',bad->'entrada');
  IF mutant_truth IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'M4_GUARD_MUTANT_SURVIVED % %',code,mutant_truth; END IF;
  RAISE NOTICE 'M4_CASES % count=% guard_mutant_detected=true',code,cases;
  applied:=lf_ops.nucleo_regla_proponer_v1(p,true);
  IF applied->>'resultado'<>'CANDIDATA' OR applied->>'version'<>'1' THEN RAISE EXCEPTION 'M4_DOOR_REJECTED % %',code,applied; END IF;
  eval:=lf_ops.nucleo_regla_evaluar_v1(code,true);
  IF eval->>'decision'<>'BLOQUEADA' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(eval->'motivos') m WHERE m->>'dimension'='JUICIO') THEN RAISE EXCEPTION 'M4_UNJUDGED_MUST_BLOCK % %',code,eval; END IF;
  IF NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_reglas r JOIN lf_ops.nucleo_regla_versiones v ON v.regla=r.codigo WHERE r.codigo=code AND r.estado='CANDIDATA' AND r.regla_legacy_id IS NULL AND v.version=1 AND v.estado='CANDIDATA' AND v.publicada_desde IS NULL AND v.exigible_desde IS NULL)
  THEN RAISE EXCEPTION 'M4_NOT_CANDIDATE_ONLY %',code; END IF;
  RAISE NOTICE 'M4_CANDIDATE %',jsonb_build_object('code',code,'cases',cases,'decision',eval->>'decision','hash',lf_ops.nucleo_hash_paquete_v1(code,1),'estado','CANDIDATA');
  n:=n+1;total_tests:=total_tests+cases;
 END LOOP;
 IF EXISTS(SELECT 1 FROM public.lf_error_knowledge WHERE codigo='LF-NUCLEO-M4-LOGICAL-FACTS-NO-RUNTIME-BINDING-20261123-001') THEN RAISE EXCEPTION 'M4_EKB_DUPLICATE'; END IF;
 INSERT INTO public.lf_error_knowledge(codigo,categoria,titulo,descripcion,causa_raiz,patron,prevencion,validacion,severidad,frecuencia,primera_vez,ultima_vez,lote_origen,estado,evidencia)
 VALUES('LF-NUCLEO-M4-LOGICAL-FACTS-NO-RUNTIME-BINDING-20261123-001','NUCLEO_REGLAS','M4 guards de seguridad con hechos lógicos pendientes de binding','Las ocho candidatas están tipadas y probadas sintéticamente, pero sin binding runtime ni juicio independiente; no equivalen a controles operativos de seguridad.','Migración de textos antes de binding físico con fuente verificable','M4_LOGICAL_GUARD_BINDING_PENDING','Exigir binding acreditado de Paulo, señal de intento real, tests de integración y juicio independiente antes de publicar.','8 candidatas; 32 casos; 8 mutantes; PG17 BEGIN/ROLLBACK; no publicar','HIGH',1,now(),now(),'M4-SECURITY-20261123','ACTIVO','docs/nucleo/LF_M4_INVENTARIO_112_PRELIMINAR_20261123.md; sandbox/lf_contract_gate_test/nucleo_ci/m4_8_candidatas_v1.json');
 IF n<>8 OR total_tests<>32 OR (SELECT count(*) FROM public.lf_error_knowledge)<>oldekb+1
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY id) FROM lf_ops.reglas r) IS DISTINCT FROM oldlegacy
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY codigo) FROM lf_ops.nucleo_reglas r WHERE codigo NOT LIKE 'M4-C0%') IS DISTINCT FROM oldrules
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) FROM lf_ops.nucleo_regla_versiones r WHERE regla NOT LIKE 'M4-C0%') IS DISTINCT FROM oldversions
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones r) IS DISTINCT FROM olddeprec
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,nodo) FROM lf_ops.nucleo_aplicaciones r WHERE regla NOT LIKE 'M4-C0%') IS DISTINCT FROM oldapps
 OR (SELECT jsonb_agg(jsonb_build_object('nodo',nd.codigo,'r',to_jsonb(e)) ORDER BY nd.codigo,e.regla) FROM lf_ops.nucleo_nodos nd CROSS JOIN LATERAL lf_ops.nucleo_reglas_efectivas_v1(nd.codigo,now()) e) IS DISTINCT FROM oldeffective
 OR (SELECT estado FROM lf_ops.nucleo_reglas WHERE codigo='REG_CHK_007')<>'CANDIDATA'
 THEN RAISE EXCEPTION 'M4_UNAUTHORIZED_DRIFT count=% tests=%',n,total_tests; END IF;
 RAISE NOTICE 'M4_PASS 8/8 candidate-only; 32/32 scoped cases; 8 guard mutants; legacy unchanged; zero deprecations';
END $m4$;
COMMIT;
